from pathlib import Pathfrom src.image_processor import validate_imagedef test_validate_image_accepts_jpg(tmp_path):    image_path = tmp_path / "test.jpg"    image_path.touch()    is_valid, error_message = validate_image(image_path)    assert is_valid is True    assert error_message == ""def test_validate_image_rejects_missing_file(tmp_path):    image_path = tmp_path / "missing.jpg"    is_valid, error_message = validate_image(image_path)    assert is_valid is False    assert "no existe" in error_messagedef test_validate_image_rejects_invalid_extension(tmp_path):    image_path = tmp_path / "test.txt"    image_path.touch()    is_valid, error_message = validate_image(image_path)    assert is_valid is False    assert "Formato de imagen no compatible" in error_message    from PIL import Imagefrom src.image_processor import prepare_imagedef test_prepare_image_resizes_large_image(tmp_path):    image_path = tmp_path / "large.jpg"    image = Image.new("RGB", (2000, 1500))    image.save(image_path)    prepared_path = prepare_image(image_path)    assert prepared_path.exists()    assert prepared_path != image_path    with Image.open(prepared_path) as prepared_image:        assert max(prepared_image.size) == 1280def test_prepare_image_keeps_small_image(tmp_path):    image_path = tmp_path / "small.jpg"    image = Image.new("RGB", (800, 600))    image.save(image_path)    prepared_path = prepare_image(image_path)    assert prepared_path == image_path